class Tool
{
    public string Label { get; }

    public Tool(string label)
    {
        Label = label;
    }

    public string Show()
    {
        return "Tool " + Label;
    }
}

class Hammer : Tool
{
    public Hammer(string label) : base(label)
    {
    }

    public string Strike()
    {
        return Label + " strikes";
    }
}

class Shed
{
    public string Check()
    {
        Hammer old = new Hammer("Old");
        return old.Show() + ", " + old.Strike();
    }
}
